local function ssid_map_template(wifi_iface)
  return {
    ["ssid"] =          { uci_secname = wifi_iface, uci_option = "ssid" }, -- override uci_secname if need
    ["apisolation"] =   { uci_option = "ap_isolation", value = ch.convert_bool },
    ["any"] =           { uci_option = "public", value = ch.convert_bool },
    ["secmode"] =       { uci_option = "security_mode", value = ch.wireless_convert_secmode },
    ["WEPkey"] =        { uci_option = "wep_key" },
    ["WPAPSKkey"] =     { uci_option = "wpa_psk_key" },
    ["pmksacache"] =    { uci_option = "pmksa_cache", value = ch.convert_bool },
    ["stationhistory"] ={ uci_option = "station_history", value = ch.convert_bool },
    ["maxassociations"]={ uci_option = "max_assoc" },
  }
end

