local function dsd_uf_get_uci_secname(_,_,lt)
  if not lt._maps_store["_uf_uci_secname"] then
     lt._maps_store["_uf_uci_secname"] = lt._maps_store["_ucicmd_result"]
  end
  return lt._maps_store["_uf_uci_secname"]
end

local dhcs_map = {
    ["poolstart"] = { uci_option = "start", value = ch.dhcs_convert_pooloffset },
    ["poolend"] = { uci_option = "limit", value = ch.dhcs_convert_poolrange },
    ["state"] = { uci_option = "ignore", value = ch.dhcs_convert_poolstate },
  }

local function ip_save_primary_preferred_in_maps_store(_,lv,lt)
  if lt["primary"] == "enabled" then
     lt._maps_store["_primary_ip"] = lv
  end
  if lt["preferred"] == "enabled" then
     lt._maps_store["_preferred_ip"] = lv
  end
end

local function ip_if_localnetwork_ip_need_to_converted(_,_,lt)
  -- do not use 'lv' here since "intf" was used to convert "netmask",
  -- the value of "intf" will be lv in such case.
  local addr = gsub(lt["addr"] or "", "/%d+", "")
  if (addr == lt._maps_store["_primary_ip"]) or (addr == lt._maps_store["_preferred_ip"]) then
     return "lan"
  end
  if not lt._maps_store["_primary_ip"] and not lt._maps_store["_primary_ip"] then
     return "lan"
  end
end

local function ip_save_first_in_maps_store(_,_,lt)
  local addr = lt["addr"]
  addr = (type(addr) == "table") and addr[1] or addr
  addr = gsub(addr or "", "/%d+", "")
  lt._maps_store["first_ip"] = addr
end

local function ip_if_ipwifi_ip_need_to_converted(_,_,lt)
  -- do not use 'lv' here since "intf" was used to convert "netmask",
  -- the value of "intf" will be lv in such case.
  local addr = gsub(lt["addr"] or "", "/%d+", "")
  if addr == lt._maps_store["first_ip"] then
     return "Guest1"
  end
end

local function ip_convert_netmask(_,_,lt)
  local netmask = match(lt["addr"] or "", "/(%d+)")
  if netmask and tonumber(netmask) >= 0 and tonumber(netmask) <= 32 then
    netmask = netmask ~= "0" and bit.lshift(bit.bnot(0), 32-netmask) or 0
  else
    netmask = 24 -- 255.255.255.0 by default
  end
  return ch.num2ipv4(netmask)
end


local voice_device_map = {
  ["FXS1"] = "fxs_dev_0",
  ["FXS2"] = "fxs_dev_1",
  ["DECT1"] = "dect_dev_0",
  ["DECT2"] = "dect_dev_1",
  ["DECT3"] = "dect_dev_2",
  ["DECT4"] = "dect_dev_3",
  ["DECT5"] = "dect_dev_4",
  ["DECT6"] = "dect_dev_5",
}

local function voice_convert_device_list(_,lv)
  if type(lv) == "string" then
     return voice_device_map[lv]
  elseif type(lv) == "table" then
     for k,v in ipairs(lv) do
         lv[k] = voice_device_map[v]
     end
     return lv
  end
end

local function get_wanmode(_,_,lt,g_user_ini)
  local wanmode = match(g_user_ini["system.ini"], "config %C*WANMode=(%S+)")
    if wanmode == "ADSL" then
      return "atm_wan eth3"
    elseif wanmode == "VDSL" then
      return "vlan_data eth3"
    elseif wanmode == "ETH" then
      return "eth4 eth3"
    end
end



local function get_laxrules(_,_,lt,g_user_ini)
  local firewall_setting = match(g_user_ini["fwlevel.ini"], "set %C*name=(%S+)")
    if firewall_setting == "Disabled" then
      return "1"
    else
      return "0"
    end
end

local function get_normalrules(_,_,lt,g_user_ini)
  local firewall_setting = match(g_user_ini["fwlevel.ini"], "set %C*name=(%S+)")
    if firewall_setting == "Standard" then
      return "1"
    else
      return "0"
    end
end

local function get_highrules(_,_,lt,g_user_ini)
  local firewall_setting = match(g_user_ini["fwlevel.ini"], "set %C*name=(%S+)")
    if firewall_setting == "BlockAll" then
      return "1"
    else
      return "0"
    end
end

local function get_zone(_,_,lt,g_user_ini)
  local firewall_setting = match(g_user_ini["fwlevel.ini"], "set %C*name=(%S+)")
    if firewall_setting == "Disabled" then
      return "REJECT"
    else
      return "DROP"
    end
end

local function get_target (_,_,lt,g_user_ini)
  local firewall_setting = match(g_user_ini["fwlevel.ini"], "set %C*name=(%S+)")
    if firewall_setting == "BlockAll" then
      return "DROP"
    else
      return "ACCEPT"
    end
end	

local function get_firewall_level(_,_,lt,g_user_ini)
  local firewall_setting = match(g_user_ini["fwlevel.ini"], "set %C*name=(%S+)")
    if firewall_setting == "Disabled" then
      return "lax"
    elseif firewall_setting == "BlockAll" then
      return "high"
    else
      return "normal"
    end
end


local service_mac_mapped = {}
function service_add_host_if_needed(_,_,lt,g_user_ini)
  local mac = match(g_user_ini["dhcs.ini"], "addr="..lt.host:gsub('%.', '%%%.').." %C+macaddr=(%S+)")
  if mac and not service_mac_mapped[mac] then
     service_mac_mapped[mac] = true
     return "add"
  end
end


local function get_mac(_,_,lt,g_user_ini)
  local mac = match(g_user_ini["dhcs.ini"], "addr="..lt.host:gsub('%.', '%%%.').." %C+macaddr=(%S+)")
  if mac ~= nil then
    return match(g_user_ini["dhcs.ini"], "addr="..lt.host:gsub('%.', '%%%.').." %C+macaddr=(%S+)")
  end	
end


local function get_name(_,_,lt,g_user_ini)
	local mac = match(g_user_ini["dhcs.ini"], "addr="..lt.host:gsub('%.', '%%%.').." %C+macaddr=(%S+)")
	if mac ~= nil then
		local hostname = match(g_user_ini["hostmgr.ini"], "mac_addr="..mac.." %C+host_name=(%S+)")
		if hostname == nil then
			hostname = match(lt.name, "%S+")
		end
		return hostname
	end
end


local function get_gwip(_,_,lt,g_user_ini)
  return match(g_user_ini["dhcs.ini"], "LocalNetwork %C*gateway=(%S+)")
end

local function get_rollbacksetting (_,_,lt,g_user_ini)
  local swversion = match(g_user_ini["cwmp.ini"], "runtimevar %C*softwareVersion=(%S+)")
  if swversion=="10.A.3.2" or swversion=="10.5.1.T" then
	return "600"
  else 
	return "0"
  end
end


